export type CreateSandbox = {
    /**
     * The name of the sandbox. If not provided, the sandbox ID will be used as the name
     */
    name?: string;
    /**
     * Immutable workload mode. Ephemeral workloads use Firecracker; standard workloads use Cloud Hypervisor.
     */
    mode: SandboxMode;
    /**
     * Guest platform capabilities to activate. Desktop also activates developer tools.
     */
    capabilities?: Array<SandboxCapability>;
    /**
     * The ID or name of the snapshot used for the sandbox
     */
    snapshot?: string;
    /**
     * OS user that runs the entrypoint, toolbox commands, sessions, terminals, SSH, the desktop and files created through the toolbox
     */
    user?: string;
    /**
     * Environment variables for the sandbox
     */
    env?: {
        [key: string]: string;
    };
    /**
     * Platform-managed secret bindings exposed as environment variables to every sandbox process. Values are resolved only for transient machine delivery.
     */
    secretEnv?: Array<SecretBindingDto>;
    /**
     * Labels for the sandbox
     */
    labels?: {
        [key: string]: string;
    };
    /**
     * Whether to block all network access for the sandbox
     */
    networkBlockAll?: boolean;
    /**
     * Comma-separated list of allowed CIDR network addresses for the sandbox
     */
    networkAllowList?: string;
    /**
     * Comma-separated list of allowed domains for the sandbox
     */
    domainAllowList?: string;
    /**
     * Maximum sandbox egress bandwidth in bits per second
     */
    egressBandwidthBps?: number;
    /**
     * Where the sandbox runs: pinned to one machine, or any matching machine. Defaults to the best matching machine nearest to the caller.
     */
    placement?: SandboxPlacementRequest;
    /**
     * Who signs the escrow vouchers that pay for the sandbox: delegated lets Snapflow's signer sign them within the session key your funding wallet granted it; client leaves each voucher for your SDK or agent to sign
     */
    voucherSigning?: VoucherSigningMode;
    /**
     * CPU cores allocated to the sandbox; the snapshot's, 2 by default
     */
    cpu?: number;
    /**
     * GPU units allocated to the sandbox
     */
    gpu?: number;
    /**
     * Preferred GPU type for the sandbox. Accepts a single value or an ordered preference list — the scheduler tries each in order and pins the sandbox to the first that has capacity.
     */
    gpuType?: Array<GpuType>;
    /**
     * Memory allocated to the sandbox in GiB; the snapshot's, 4 by default
     */
    memory?: number;
    /**
     * Disk space allocated to the sandbox in GiB; the snapshot's, 10 by default
     */
    disk?: number;
    /**
     * Auto-stop interval in minutes (0 means disabled)
     */
    autoStopInterval?: number;
    /**
     * Minutes the sandbox stays stopped on its machine before it is archived; 0 uses the organization's archiveAfterStoppedDays
     */
    autoArchiveInterval?: number;
    /**
     * Auto-delete interval in minutes (negative value means disabled, 0 means delete immediately upon stopping)
     */
    autoDeleteInterval?: number;
    /**
     * Array of volumes to attach to the sandbox
     */
    volumes?: Array<SandboxVolume>;
    /**
     * Build information for the sandbox
     */
    buildInfo?: CreateBuildInfo;
    /**
     * ID or name of an existing sandbox to link the new sandbox to. The new sandbox will be scheduled on the same machine as the linked sandbox so a local network can be established between them. Linked sandboxes must use ephemeral mode and cannot themselves be linked to another sandbox.
     */
    linkedSandbox?: string;
};

